def is_board_valid(board):
    for i in range(9):
        row = [board[i][j] for j in range(9) if board[i][j] != '.']
        col = [board[j][i] for j in range(9) if board[j][i] != '.']
        if len(row) != len(set(row)) or len(col) != len(set(col)):   # check whole board at once
            return False
    for br in range(0, 9, 3):
        for bc in range(0, 9, 3):
            box = [board[br+i][bc+j] for i in range(3) for j in range(3) if board[br+i][bc+j] != '.']
            if len(box) != len(set(box)):
                return False
    return True

# Conceptually: try every digit for every empty cell, then call is_board_valid()
# only once the entire board has been filled. Extremely wasteful in practice.

