public class Main {
    static char[][] board;

    static boolean isValid(int r, int c, char ch) {
        for (int i = 0; i < 9; i++) {
            if (board[r][i] == ch || board[i][c] == ch) return false;
            if (board[3 * (r / 3) + i / 3][3 * (c / 3) + i % 3] == ch) return false;
        }
        return true;
    }

    static boolean solve() {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    for (char d = '1'; d <= '9'; d++) {
                        if (isValid(r, c, d)) {                  // check BEFORE placing
                            board[r][c] = d;
                            if (solve()) return true;
                            board[r][c] = '.';                    // undo (backtrack)
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }

    static void solveSudoku(char[][] b) {
        board = b;
        solve();
    }
}

