using namespace std;

vector<vector<char>>* boardPtr;

bool isValid(int r, int c, char ch) {
    auto& board = *boardPtr;
    for (int i = 0; i < 9; i++) {
        if (board[r][i] == ch || board[i][c] == ch) return false;
        if (board[3 * (r / 3) + i / 3][3 * (c / 3) + i % 3] == ch) return false;
    }
    return true;
}

bool solve() {
    auto& board = *boardPtr;
    for (int r = 0; r < 9; r++) {
        for (int c = 0; c < 9; c++) {
            if (board[r][c] == '.') {
                for (char d = '1'; d <= '9'; d++) {
                    if (isValid(r, c, d)) {                       // check BEFORE placing
                        board[r][c] = d;
                        if (solve()) return true;
                        board[r][c] = '.';                         // undo (backtrack)
                    }
                }
                return false;
            }
        }
    }
    return true;
}

void solveSudoku(vector<vector<char>>& b) {
    boardPtr = &b;
    solve();
}
